def star(cx, cy, r):
    pts = []
    for i in range(10):
        ang = -math.pi / 2 + i * math.pi / 5
        rr = r if i % 2 == 0 else r * 0.42
        pts += [round(cx + rr * math.cos(ang), 1), round(cy + rr * math.sin(ang), 1)]
    return pts

