     MATCH("Match each term with its meaning.", [("Transparency", "Information is open to the public"), ("Accountability", "Leaders explain their use of power and money"), ("Nepotism", "Favouring relatives")], "These terms are central to governance."),
     MCQ("Which helps to fight corruption?", "Refusing to give or take bribes", ["Giving small bribes", "Hiding wrongdoing", "Ignoring the law"], "Individual refusal matters.", tier="approfondissement"),
